// Validate reports every invalid external scan setting.
func (c PortScanConf) Validate() (errs []error) {
	if c.IsZero() {
		return nil
	}
	if c.ScannerBinPath == "" {
		errs = append(errs, fmt.Errorf("scannerBinPath is required for external port scanning"))
	} else if info, err := os.Stat(c.ScannerBinPath); err != nil {
		errs = append(errs, fmt.Errorf("scannerBinPath %q: %w", c.ScannerBinPath, err))
	} else if !info.Mode().IsRegular() || info.Mode().Perm()&0111 == 0 {
		errs = append(errs, fmt.Errorf("scannerBinPath %q is not an executable file", c.ScannerBinPath))
	}
	if len(c.ScanTechniques) > 1 {
		errs = append(errs, fmt.Errorf("multiple scan techniques are not supported"))
	}
	techniques := c.GetScanTechniques()
	if len(techniques) == 0 && c.SourcePort != "" && !c.HasPrivileged {
		errs = append(errs, fmt.Errorf("sourcePort is incompatible with TCPConnect"))
	}
	for _, raw := range c.ScanTechniques {
		technique := (&PortScanConf{ScanTechniques: []string{raw}}).GetScanTechniques()[0]
		if technique == NotSupportTechnique {
			errs = append(errs, fmt.Errorf("unsupported scan technique %q", raw))
		} else if !c.HasPrivileged && technique != TCPConnect {
			errs = append(errs, fmt.Errorf("scan technique %s requires hasPrivileged", technique))
		} else if technique == TCPConnect && c.SourcePort != "" {
			errs = append(errs, fmt.Errorf("sourcePort is incompatible with TCPConnect"))
		}
	}
	if c.SourcePort != "" {
		port, err := strconv.Atoi(c.SourcePort)
		if err != nil || port < 0 || port > 65535 {
			errs = append(errs, fmt.Errorf("sourcePort %q must be an integer in [0,65535]", c.SourcePort))
		} else if port == 0 {
			errs = append(errs, fmt.Errorf("sourcePort 0 is not a usable source port"))
		}
	}
	if c.HasPrivileged && c.ScannerBinPath != "" && os.Geteuid() != 0 {
		output, err := exec.Command("getcap", c.ScannerBinPath).CombinedOutput()
		if err != nil {
			errs = append(errs, fmt.Errorf("cannot check scannerBinPath capabilities: %w: %s", err, strings.TrimSpace(string(output))))
		} else {
			fields := strings.Fields(string(output))
			if len(fields) < 2 || !strings.Contains(string(output), "=") {
				errs = append(errs, fmt.Errorf("missing or malformed scannerBinPath capability data"))
			} else if !strings.Contains(string(output), "cap_net_raw") || !strings.Contains(string(output), "cap_net_admin") {
				errs = append(errs, fmt.Errorf("scannerBinPath requires cap_net_raw and cap_net_admin capabilities"))
			}
		}
	}
	return
}
package config

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestPortScanTechniquesAndValidation(t *testing.T) {
	names := []string{"SS", "st", "Sa", "sW", "Sm", "SN", "sf", "SX", "unknown"}
	want := []ScanTechnique{TCPSYN, TCPConnect, TCPACK, TCPWindow, TCPMaimon, TCPNull, TCPFIN, TCPXmas, NotSupportTechnique}
	c := PortScanConf{ScanTechniques: names}
	got := c.GetScanTechniques()
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("technique %q: got %q, want %q", names[i], got[i], want[i])
		}
	}
	if len((&PortScanConf{}).GetScanTechniques()) != 0 {
		t.Fatal("empty techniques should yield empty slice")
	}
	c.ScanTechniques = []string{"invalid", "also-invalid"}
	if got := c.GetScanTechniques(); len(got) != 1 || got[0] != NotSupportTechnique {
		t.Fatalf("unknown technique: %v", got)
	}
	if !(PortScanConf{}).IsZero() {
		t.Fatal("zero config not zero")
	}
	if (PortScanConf{HasPrivileged: true}).IsZero() {
		t.Fatal("privilege flag should make config nonzero")
	}

	bin := filepath.Join(t.TempDir(), "nmap")
	if err := os.WriteFile(bin, []byte("#!/bin/sh\nexit 0\n"), 0755); err != nil {
		t.Fatal(err)
	}
	cases := []struct {
		name string
		conf PortScanConf
		want string
	}{
		{"connect", PortScanConf{ScannerBinPath: bin, ScanTechniques: []string{"sT"}}, ""},
		{"unsupported", PortScanConf{ScannerBinPath: bin, ScanTechniques: []string{"bad"}}, "unsupported"},
		{"multiple", PortScanConf{ScannerBinPath: bin, ScanTechniques: []string{"sT", "sT"}}, "multiple"},
		{"privilege", PortScanConf{ScannerBinPath: bin, ScanTechniques: []string{"sS"}}, "hasPrivileged"},
		{"connect source", PortScanConf{ScannerBinPath: bin, ScanTechniques: []string{"sT"}, SourcePort: "443"}, "incompatible"},
		{"default connect source", PortScanConf{ScannerBinPath: bin, SourcePort: "443"}, "incompatible"},
		{"port range", PortScanConf{ScannerBinPath: bin, SourcePort: "65536"}, "[0,65535]"},
		{"port zero", PortScanConf{ScannerBinPath: bin, SourcePort: "0"}, "sourcePort 0"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			errs := tc.conf.Validate()
			if tc.want == "" {
				if len(errs) != 0 {
					t.Fatalf("unexpected errors: %v", errs)
				}
				return
			}
			for _, err := range errs {
				if strings.Contains(err.Error(), tc.want) {
					return
				}
			}
			t.Fatalf("expected %q in %v", tc.want, errs)
		})
	}
}

